#include "../include/core.hpp"
mp::json dagTrace;
#include "../build/brs_trace.inc"
using namespace mp;
json sample(Pose q,const Path&p,double step=.2){json a=json::array();double d=0;for(auto&v:p){int n=std::max(1,int(std::ceil(v.L/step)));for(int i=0;i<n;i++){auto x=advance(q,v,v.L*i/n);a.push_back({x.x,x.y,x.t,d+v.L*i/n,v.gear});}q=advance(q,v);d+=v.L;}a.push_back({q.x,q.y,q.t,d,p.empty()?1:p.back().gear});return a;}
std::string file(const std::string&root,int id){std::ostringstream s;s<<root<<"/benchmark/case_"<<std::setw(3)<<std::setfill('0')<<id<<".json";return s.str();}
json read(const std::string&f){std::ifstream in(f);json j;in>>j;return j;}
bool same(const Path&a,const Path&b){if(a.size()!=b.size())return false;for(size_t i=0;i<a.size();i++)if(std::abs(a[i].L-b[i].L)>1e-5||std::abs(a[i].k0-b[i].k0)>1e-8||std::abs(a[i].k1-b[i].k1)>1e-8||a[i].gear!=b[i].gear)return false;return true;}
int main(int argc,char**argv){try{if(argc<4)return 1;std::string root=argv[1],results=argv[2],out=argv[3];Params params=readParams(root+"/benchmark/parameters.json");std::ifstream in(results);std::string line;std::map<int,std::vector<json>>all;while(std::getline(in,line)){auto r=json::parse(line);all[r["case"]].push_back(r);}for(int id:{3,17,18,19,22,27,30,55,100}){Scene s=readScene(file(root,id));World w(s,params);json z;z["scene"]=read(file(root,id));z["methods"]=json::array();json main;for(auto&r:all[id]){if(!r["success"].get<bool>())continue;Path p=path(r["path"]);auto t=profile(p,s.truck,params,true);json v=r;v["q"]=sample(s.start,p);v["events"]=t.events;v["speed_profile"]=t.profile;z["methods"].push_back(v);if(r["method"]=="BRS")main=v;}z["selected"]=main;Path full=path(main["path"]);int depth=main["prefix_depth"];if(depth){Path pre(full.begin(),full.begin()+3*depth);z["selected_prefix"]=sample(s.start,pre);z["prefix_trials"]=json::array();for(double L:{4.,8.,12.})for(int g:{-1,1})for(double side:{-1.,1.}){Path p=prefix(g,side,L,s.truck.R);z["prefix_trials"].push_back({{"q",sample(s.start,p)},{"safe",w.check(s.start,p,0,true)}});}}
if(id==18||id==55){int kind=id==18?2:3;Path forward,reverse;for(auto&p:full)(p.gear>0?forward:reverse).push_back(p);Path fan=kind==2?invert(reverse):forward;Pose fanRoot=kind==2?s.goal:s.start;Path connection=kind==2?forward:invert(Path(reverse.begin(),reverse.end()-1));Pose connRoot=kind==2?s.start:anchor(s);z["connector"]={{"q",sample(connRoot,connection)},{"path",jpath(connection)},{"start",jpose(connRoot)}};z["fans"]=json::array();bool matched=false;for(int level=1;level<=3&&!matched;level++){json candidates=json::array();std::vector<double>rad=level>=2?std::vector<double>{1,1.4,1.8,2.4}:std::vector<double>{1,1.4},ramp=level==3?std::vector<double>{1}:std::vector<double>{4,8},stems=kind==2?std::vector<double>{s.tail,s.tail+8,s.tail+16}:std::vector<double>{0,8};for(double L:stems)for(double R:scales(s.truck.R,rad))for(double rr:ramp)for(int side:{-1,1})for(int angle=0;angle<=150;angle+=level==3?1:15){if(angle==0&&side<0)continue;Path p;if(L>0)p.push_back({L,0,0,1});p=cat(p,turn(side*angle*pi/180.,R,rr));if(p.empty())continue;bool chosen=same(p,fan);matched=matched||chosen;candidates.push_back({{"q",sample(fanRoot,p)},{"safe",w.check(fanRoot,p,0,true)},{"selected",chosen},{"angle",angle},{"radius",R},{"ramp",rr},{"stem",L}});}if(matched){z["fans"]=candidates;z["fan_level"]=level;}}if(!matched)throw std::runtime_error("Selected fan not found for "+std::to_string(id));z["kind"]=kind;z["cusp"]=jpose(endpoint(fanRoot,fan));}
if(id==17){Context context(30,.2);context.original=&s;ctx=&context;dagTrace={{"states",json::array()},{"edges",json::array()}};auto c=dag(s,w);z["coarse"]=dagTrace;z["coarse"]["success"]=c.success;if(c.success){z["coarse"]["q"]=sample(anchor(s),c.curve);dagTrace={{"states",json::array()},{"edges",json::array()}};context.stopAt=context.elapsed()+.2;try{auto f=dag(s,w,&c);if(f.success)dagTrace["q"]=sample(anchor(s),f.curve);}catch(Timeout&){}z["fine"]=dagTrace;}ctx=nullptr;for(auto key:{"coarse","fine"})if(z.contains(key))for(auto&e:z[key]["edges"])e["q"]=sample(pose(e["start"]),path(e["path"]));}
std::ofstream f(out+"/case_"+std::to_string(id)+".json");f<<z.dump();std::cout<<"Exported "<<id<<std::endl;}return 0;}catch(std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}}
